import{_ as e,o as t,c as i,a2 as l}from"./chunks/framework.CFuv5BrO.js";const k=JSON.parse('{"title":"D1.6 · Stage 1 发布","description":"Hearth D1.6 开发增量：一个可以持续试用的本地产品，具备明确的范围、已知限制、恢复方式和指标基线。","frontmatter":{"title":"D1.6 · Stage 1 发布","description":"Hearth D1.6 开发增量：一个可以持续试用的本地产品，具备明确的范围、已知限制、恢复方式和指标基线。","outline":[2,3]},"headers":[],"relativePath":"delivery/stage-1/d1-6.md","filePath":"delivery/stage-1/d1-6.md","lastUpdated":null}'),s={name:"delivery/stage-1/d1-6.md"};function r(h,a,d,o,n,c){return t(),i("div",null,[...a[0]||(a[0]=[l(`<p class="eyebrow">STAGE 1 · D1.6 · 6 / 6</p><h1 id="d1-6-·-stage-1-发布" tabindex="-1">D1.6 · Stage 1 发布 <a class="header-anchor" href="#d1-6-·-stage-1-发布" aria-label="Permalink to &quot;D1.6 · Stage 1 发布&quot;">​</a></h1><p class="lead">把 MVP 放进可长期试用的本地环境，完成范围、限制、安装、备份、升级与指标基线。</p><p class="page-meta">STAGE 1 · D1.6 · 1 个纵向切片 · 4 个工作包</p><div class="section-grid"><div><strong>用户可见结果</strong>一个可以持续试用的本地产品，具备明确的范围、已知限制、恢复方式和指标基线。</div><div><strong>完成门槛</strong>Stage 1 退出条件全部满足；MVP 没有被后续内核工作破坏；用户能独立使用，不依赖开发者手工运维。</div></div><h2 id="这一步要交付什么" tabindex="-1">这一步要交付什么 <a class="header-anchor" href="#这一步要交付什么" aria-label="Permalink to &quot;这一步要交付什么&quot;">​</a></h2><p>一个可以持续试用的本地产品，具备明确的范围、已知限制、恢复方式和指标基线。</p><p>Stage 1 的顺序是先有真实短闭环，再有安全副作用，最后扩大任务族和恢复覆盖；不能在空内核上先堆模块。</p><h2 id="开始前" tabindex="-1">开始前 <a class="header-anchor" href="#开始前" aria-label="Permalink to &quot;开始前&quot;">​</a></h2><ul><li>Stage 0 的 12 个任务、原型、协议、评测与安全基线已经评审通过。</li><li>默认任务楔子是研究/文档整理；如果首位用户更依赖代码任务，可以替换楔子，但纵向结构不能改变。</li><li>本地开发环境、SQLite、可隔离 workspace 和 Web 构建链路可用。</li><li>D1.5 的交付物已经验收；未通过时不进入本增量。</li></ul><h2 id="四个实施工作包" tabindex="-1">四个实施工作包 <a class="header-anchor" href="#四个实施工作包" aria-label="Permalink to &quot;四个实施工作包&quot;">​</a></h2><blockquote><p>每个工作包都要产生可运行的代码、可复现的验证或明确的界面结果；只写接口或只做页面都不算完成。</p></blockquote><h3 id="_01-·-stage-1-出口审计" tabindex="-1">01 · Stage 1 出口审计 <a class="header-anchor" href="#_01-·-stage-1-出口审计" aria-label="Permalink to &quot;01 · Stage 1 出口审计&quot;">​</a></h3><p>逐条收集 MVP、恢复、副作用、任务族和成本门槛的证据，缺一项就停留在当前阶段；不要用后续路线图替代当前验收。</p><h3 id="_02-·-故障与安全复核" tabindex="-1">02 · 故障与安全复核 <a class="header-anchor" href="#_02-·-故障与安全复核" aria-label="Permalink to &quot;02 · 故障与安全复核&quot;">​</a></h3><p>完成 200 次故障注入、崩溃恢复、重复投递、越权和秘密检查；记录未解决风险、规避方式和是否阻断发布。</p><h3 id="_03-·-安装与支持文档" tabindex="-1">03 · 安装与支持文档 <a class="header-anchor" href="#_03-·-安装与支持文档" aria-label="Permalink to &quot;03 · 安装与支持文档&quot;">​</a></h3><p>从空目录完成安装、启动、创建任务、重启恢复和导出；写清前置条件、已知限制、诊断命令和回滚方式。</p><h3 id="_04-·-发布说明与下一阶段入口" tabindex="-1">04 · 发布说明与下一阶段入口 <a class="header-anchor" href="#_04-·-发布说明与下一阶段入口" aria-label="Permalink to &quot;04 · 发布说明与下一阶段入口&quot;">​</a></h3><p>发布 Stage 1 版本说明，说明可用任务族、不能做什么、数据位置和升级路径；把 Stage 2 的只读优先级写进下一阶段入口。</p><h2 id="工程落点" tabindex="-1">工程落点 <a class="header-anchor" href="#工程落点" aria-label="Permalink to &quot;工程落点&quot;">​</a></h2><h3 id="主要目录与模块" tabindex="-1">主要目录与模块 <a class="header-anchor" href="#主要目录与模块" aria-label="Permalink to &quot;主要目录与模块&quot;">​</a></h3><ul><li><code>apps/hearthd</code> — 单进程常驻、Gateway、Control、Harness 与 SSE</li><li><code>packages/eventlog</code> — SQLite WAL、事件、投影、migration 与 replay</li><li><code>packages/harness</code> — Ticket、Run、lease、outbox、恢复与死信</li><li><code>packages/executors/codex</code> — Codex adapter、workspace 与结构化输出</li><li><code>packages/policy</code> — Policy、Mandate、Approval 与风险等级</li><li><code>packages/artifacts</code> — 内容寻址产物、哈希、版本与验证器</li><li><code>apps/web</code> — 任务卡、详情/时间线、审批、产物与恢复</li></ul><h3 id="关键接口" tabindex="-1">关键接口 <a class="header-anchor" href="#关键接口" aria-label="Permalink to &quot;关键接口&quot;">​</a></h3><table tabindex="0"><thead><tr><th>接口</th><th>必须保持的契约</th></tr></thead><tbody><tr><td><code>Run</code></td><td>runId、ticketId、state、checkpoint、budget、terminalReason；一次执行尝试只能有一个终态。</td></tr><tr><td><code>Ticket / Lease</code></td><td>owner、scope、expiresAt、fencingToken；同一 Ticket 同时最多一个有效写者。</td></tr><tr><td><code>TaskPack</code></td><td>objective、inputs、constraints、outputSchema、acceptance、budget、permissions；执行器只在该包内工作。</td></tr><tr><td><code>Effect / Receipt</code></td><td>effectIntent、approvalId、idempotencyKey、receipt、reconciliation；不确定结果先对账，不盲目重试。</td></tr></tbody></table><h3 id="共享验证命令" tabindex="-1">共享验证命令 <a class="header-anchor" href="#共享验证命令" aria-label="Permalink to &quot;共享验证命令&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev：hearthd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 与</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Web</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 同时启动</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:fault：kill</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -9、断网、超时、重复投递</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:e2e：创建→取消→重试→审批→产物→恢复</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> eval:mvp：10</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 个真实任务与基线对比</span></span></code></pre></div><h2 id="验收演练" tabindex="-1">验收演练 <a class="header-anchor" href="#验收演练" aria-label="Permalink to &quot;验收演练&quot;">​</a></h2><ol><li>从干净的数据目录启动 hearthd，打开 <a href="/hearth-os/delivery/stage-1/d1-6.html">D1.6 页面</a>，确认当前页面没有依赖浏览器缓存或手工种子数据。</li><li>按顺序完成四个工作包：Stage 1 出口审计、故障与安全复核、安装与支持文档、发布说明与下一阶段入口。每完成一个工作包，保存对应测试输出、截图或产物版本。</li><li>复现失败案例“进程崩溃或重启”。页面必须显示“任务详情显示最后已知状态、未完成步骤和“继续/取消/重试”。”，然后按“从 Event Log 重放并重新领取 lease，禁止静默丢弃任务。”恢复；不得出现重复副作用或未登记状态。</li><li>重启服务并重新打开任务，确认运行状态、审批、产物和恢复入口都来自持久投影，而不是只存在于当前页面。</li><li>运行上方的共享验证命令并导出证据。完成门槛是：Stage 1 退出条件全部满足；MVP 没有被后续内核工作破坏；用户能独立使用，不依赖开发者手工运维。</li></ol><h2 id="交付物" tabindex="-1">交付物 <a class="header-anchor" href="#交付物" aria-label="Permalink to &quot;交付物&quot;">​</a></h2><ul><li>10 个真实任务报告</li><li>与两条基线的对比</li><li>安装/备份/升级/导出说明</li><li>Stage 1 安全与评测报告</li></ul><h2 id="完成判定" tabindex="-1">完成判定 <a class="header-anchor" href="#完成判定" aria-label="Permalink to &quot;完成判定&quot;">​</a></h2><ul><li>[ ] Stage 1 退出条件全部满足；MVP 没有被后续内核工作破坏；用户能独立使用，不依赖开发者手工运维。</li><li>[ ] 交付物已经和契约、任务卡投影保持一致，没有未登记的字段或状态。</li><li>[ ] 至少一个失败路径有可操作恢复，关键动作留下审计事件。</li><li>[ ] 演示不依赖手工修改数据库、只在终端拼接命令，或永久 mock。</li></ul><h2 id="失败与恢复" tabindex="-1">失败与恢复 <a class="header-anchor" href="#失败与恢复" aria-label="Permalink to &quot;失败与恢复&quot;">​</a></h2><table tabindex="0"><thead><tr><th>情况</th><th>用户看到</th><th>恢复动作</th></tr></thead><tbody><tr><td>进程崩溃或重启</td><td>任务详情显示最后已知状态、未完成步骤和“继续/取消/重试”。</td><td>从 Event Log 重放并重新领取 lease，禁止静默丢弃任务。</td></tr><tr><td>外部动作重复</td><td>系统显示“正在对账”，不生成第二个成功回执。</td><td>按幂等键查询 sink，确认已完成后补写 Receipt 或走补偿。</td></tr><tr><td>副作用结果不确定</td><td>任务进入“等待确认”，隐藏自动重试按钮。</td><td>先查询外部系统或人工核对，再决定重试、补偿或关闭。</td></tr></tbody></table><h2 id="本增量不包含" tabindex="-1">本增量不包含 <a class="header-anchor" href="#本增量不包含" aria-label="Permalink to &quot;本增量不包含&quot;">​</a></h2><ul><li>不允许只靠 CLI、日志或数据库证明 MVP 可用。</li><li>不在恢复与审批未稳定前扩大任务族。</li><li>不把永久 mock 结果当成真实执行。</li></ul><h2 id="来源与下一步" tabindex="-1">来源与下一步 <a class="header-anchor" href="#来源与下一步" aria-label="Permalink to &quot;来源与下一步&quot;">​</a></h2><h3 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h3><ul><li><a href="/hearth-os/architecture/durable-execution.html">持久执行与恢复</a></li><li><a href="/hearth-os/architecture/executor-model.html">执行器模型</a></li><li><a href="/hearth-os/architecture/execution-safety.html">执行安全与副作用</a></li><li><a href="/hearth-os/architecture/frontend-experience.html">前端与移动体验</a></li></ul><h3 id="完成后的下一步" tabindex="-1">完成后的下一步 <a class="header-anchor" href="#完成后的下一步" aria-label="Permalink to &quot;完成后的下一步&quot;">​</a></h3><p>返回 <a href="/hearth-os/delivery/stage-1.html">Stage 1 · 持久内核与 MVP</a>，确认全部退出条件后进入 <a href="/hearth-os/delivery/stage-2.html">Stage 2</a>。</p>`,42)])])}const u=e(s,[["render",r]]);export{k as __pageData,u as default};
